def transform(grid):
    g = np.array(grid)
    H, W = g.shape
    out = g.copy()
    fg = 5
    # mark cells lying on a diagonal run of >= 3 foreground cells
    onrun = set()
    for y in range(H):
        for x in range(W):
            for dy, dx in ((1, 1), (1, -1)):
                pts = [(y + k*dy, x + k*dx) for k in range(3)]
                if all(0 <= py < H and 0 <= px < W and g[py, px] == fg for py, px in pts):
                    onrun.update(pts)
    for comp in components(g == fg, diagonal=True):
        if any(c in onrun for c in comp):
            for (y, x) in comp:
                out[y, x] = 8
            emit(out, f"Component of 5s at {bbox(comp)} contains a diagonal line of 3+ cells -> recolour it to 8")
    emit(out, "All components containing a 3-long diagonal are recoloured; others stay 5")
    return out
